#!/usr/bin/env bash
# Builds the Rust core for Apple platforms and packages it for the Swift package
# clients/apple/Packages/CrisisCore:
#
#   * a static library per platform (iOS device, iOS simulator, macOS), combined into an XCFramework;
#   * the Swift bindings generated by UniFFI;
#   * Sources/CrisisCore/Generated/CoreBuildInfo.swift, which tells the app and its tests what was built.
#
# Usage: scripts/build-apple.sh [--profile dev|release] [--sqlcipher] [--universal] [--platforms LIST]
#
#   --profile dev|release   Cargo profile (default: dev).
#   --sqlcipher             Build with the `sqlcipher` feature (encrypted database; vendored OpenSSL).
#   --universal             Also build the x86_64 slices (Intel simulator, Intel Macs). By default only the
#                           arm64 slices are built, plus x86_64 when this Mac is an Intel one.
#   --platforms LIST        Comma-separated subset of: ios, sim, mac (default: ios,sim,mac).
#
# Needs macOS with Xcode (xcodebuild, lipo) and Rust. Missing Rust targets are installed with rustup.
set -euo pipefail

cd "$(dirname "$0")/.."

profile="dev"
sqlcipher="false"
universal="false"
platforms="ios,sim,mac"

while [ $# -gt 0 ]; do
    case "$1" in
        --profile) profile="${2:?--profile needs dev or release}"; shift 2 ;;
        --sqlcipher) sqlcipher="true"; shift ;;
        --universal) universal="true"; shift ;;
        --platforms) platforms="${2:?--platforms needs a list}"; shift 2 ;;
        -h|--help) sed -n '2,19p' "$0"; exit 0 ;;
        *) echo "unknown option: $1" >&2; exit 2 ;;
    esac
done

case "$profile" in
    dev) cargo_profile_args=(); out_dir="debug" ;;
    release) cargo_profile_args=(--release); out_dir="release" ;;
    *) echo "--profile must be dev or release" >&2; exit 2 ;;
esac

if [ "$(uname -s)" != "Darwin" ]; then
    echo "This script needs macOS (Xcode, lipo, xcodebuild)." >&2
    exit 1
fi
for tool in xcodebuild lipo cargo; do
    command -v "$tool" >/dev/null || { echo "missing tool: $tool" >&2; exit 1; }
done

# The oldest systems the app supports; they decide the minimum OS version recorded in the libraries and are
# used by the C compiler for SQLite and OpenSSL.
export IPHONEOS_DEPLOYMENT_TARGET="${IPHONEOS_DEPLOYMENT_TARGET:-17.0}"
export MACOSX_DEPLOYMENT_TARGET="${MACOSX_DEPLOYMENT_TARGET:-14.0}"

feature_args=()
if [ "$sqlcipher" = "true" ]; then
    feature_args=(--features sqlcipher)
fi

host_arch="$(uname -m)"
want() { case ",$platforms," in *",$1,"*) return 0 ;; *) return 1 ;; esac; }

ios_targets=""
sim_targets=""
mac_targets=""
if want ios; then ios_targets="aarch64-apple-ios"; fi
if want sim; then
    sim_targets="aarch64-apple-ios-sim"
    if [ "$universal" = "true" ] || [ "$host_arch" = "x86_64" ]; then sim_targets="$sim_targets x86_64-apple-ios"; fi
fi
if want mac; then
    mac_targets="aarch64-apple-darwin"
    if [ "$universal" = "true" ] || [ "$host_arch" = "x86_64" ]; then mac_targets="$mac_targets x86_64-apple-darwin"; fi
fi

all_targets="$ios_targets $sim_targets $mac_targets"
if [ -z "$(echo "$all_targets" | tr -d ' ')" ]; then
    echo "no platform selected" >&2
    exit 2
fi

package_dir="clients/apple/Packages/CrisisCore"
work_dir="target/apple/$profile"
rm -rf "$work_dir"
mkdir -p "$work_dir/headers"

if command -v rustup >/dev/null; then
    for target in $all_targets; do
        rustup target add "$target"
    done
fi

echo "==> Building the core ($profile, sqlcipher=$sqlcipher) for: $all_targets"
for target in $all_targets; do
    # Only the static library: the cdylib of the same crate is for Android and is not needed here.
    cargo rustc -p ffi --lib --crate-type staticlib --target "$target" \
        ${cargo_profile_args[@]+"${cargo_profile_args[@]}"} ${feature_args[@]+"${feature_args[@]}"}
done

lib_of() { echo "target/$1/$out_dir/libcrisis_core.a"; }

# A platform with several architectures needs one fat library.
fat_library() {
    name="$1"
    shift
    output="$work_dir/$name/libcrisis_core.a"
    mkdir -p "$work_dir/$name"
    inputs=()
    for target in "$@"; do inputs+=("$(lib_of "$target")"); done
    if [ "${#inputs[@]}" -eq 1 ]; then
        cp "${inputs[0]}" "$output"
    else
        lipo -create "${inputs[@]}" -output "$output"
    fi
    echo "$output"
}

echo "==> Generating the Swift bindings"
scripts/gen-bindings.sh swift
bindings="target/bindings/swift"
for file in crisis_core.swift crisis_coreFFI.h crisis_coreFFI.modulemap; do
    [ -f "$bindings/$file" ] || { echo "UniFFI did not produce $bindings/$file" >&2; exit 1; }
done
cp "$bindings/crisis_coreFFI.h" "$work_dir/headers/crisis_coreFFI.h"
cp "$bindings/crisis_coreFFI.modulemap" "$work_dir/headers/module.modulemap"

echo "==> Creating the XCFramework"
xcframework_args=()
slices=""
if [ -n "$ios_targets" ]; then
    lib="$(fat_library ios $ios_targets)"
    xcframework_args+=(-library "$lib" -headers "$work_dir/headers")
    slices="$slices ios-arm64"
fi
if [ -n "$sim_targets" ]; then
    lib="$(fat_library sim $sim_targets)"
    xcframework_args+=(-library "$lib" -headers "$work_dir/headers")
    slices="$slices ios-simulator"
fi
if [ -n "$mac_targets" ]; then
    lib="$(fat_library mac $mac_targets)"
    xcframework_args+=(-library "$lib" -headers "$work_dir/headers")
    slices="$slices macos"
fi

framework="$package_dir/CrisisCoreFFI.xcframework"
rm -rf "$framework"
xcodebuild -create-xcframework "${xcframework_args[@]}" -output "$framework"

generated="$package_dir/Sources/CrisisCore/Generated"
mkdir -p "$generated"
cp "$bindings/crisis_core.swift" "$generated/crisis_core.swift"

revision="$(git rev-parse --short HEAD 2>/dev/null || echo unknown)"
cat > "$generated/CoreBuildInfo.swift" <<SWIFT
// Generated by scripts/build-apple.sh. Do not edit and do not commit.

/// What the Rust core in this build was compiled with.
public enum CoreBuildInfo {
    /// The Cargo profile: "dev" or "release".
    public static let profile = "$profile"
    /// Whether the core can open an encrypted (SQLCipher) database.
    public static let sqlcipher = $sqlcipher
    /// The slices of the XCFramework.
    public static let slices = "$(echo "$slices" | sed 's/^ //')"
    /// The git revision of the sources.
    public static let revision = "$revision"

    /// One line for logs and the self-test screen.
    public static var summary: String {
        "\(profile), \(sqlcipher ? "SQLCipher" : "no SQLCipher"), \(slices), \(revision)"
    }
}
SWIFT

echo "==> Done: $framework"
echo "    slices:$slices"
